mapper.select:
select count(c.id) from collisions c where 1=1
and c.company_id = ${companyId}
and c.report_number like '%${reportNumber}%'

select c.*, cf.id as "cf_id", res.id as "cf_resourcesId", res.file_name as "cf_fileName", res.extension as "cf_extension", res.size as "cf_size", res.content_type as "cf_contentType", cf.description as "cf_description", cf.type as "cf_type", cf.status as "cf_status" from ( select cl.id as "id", cl.report_number as "reportNumber", cl.collision_date as "collisionDate", cl.collision_time as "collisionTime", cl.time_zone as "timeZone", cl.city as "city", cl.zip_code as "zipCode", cl.type_of_cargo as "typeOfCargo", s.id as "stateId", s.name as "stateName", com.id as "companyId", com.name as "companyName", t.id as "truckId", t.unit as "truckUnit", d.id as "driverId", d.first_name || ' ' || d.last_name as "driverName", u.id as "createdById", u.name as "createdByName", cl.created as "created" from collisions cl left join states s on s.id = cl.state_id left join companies com on com.id = cl.company_id left join trucks t on t.id = cl.truck_id left join drivers d on d.id = cl.driver_id left join users u on u.id = cl.created_by_id where 1=1
and cl.company_id = ${companyId}
and cl.report_number like '%${reportNumber}%'
limit ${rowsPerPage} offset ${page-1} * ${rowsPerPage}
) c left join collision_files cf on cf.collision_id = c.id and cf.status = 'ACTIVE' left join resources res on res.id = cf.resource_id
